import java.io.*;import java.util.*;public class Main{private static int digitSum(int x){int sum=0;while(x>0){sum+=x%10;x/=10;}return sum;}public static void main(String[] args) throws Exception{BufferedReader br=new BufferedReader(new InputStreamReader(System.in));StringBuilder out=new StringBuilder();int T=Integer.parseInt(br.readLine().trim());for(int tc=0;tc<T;tc++){int N=Integer.parseInt(br.readLine().trim());int chef=0,morty=0;for(int i=0;i<N;i++){String line=br.readLine();while(line!=null&&line.trim().isEmpty()){line=br.readLine();}StringTokenizer st=new StringTokenizer(line);int A=Integer.parseInt(st.nextToken());int B=Integer.parseInt(st.nextToken());int sA=digitSum(A);int sB=digitSum(B);if(sA>sB)chef++;else if(sB>sA)morty++;else{chef++;morty++;}}if(chef>morty)out.append("0 ").append(chef);else if(morty>chef)out.append("1 ").append(morty);else out.append("2 ").append(chef);if(tc<T-1)out.append('\n');}System.out.print(out.toString());}}